:10,"printed_page":null,"locator":{"type":"paragraph_range","value":"71 e 72"},"boundary_role":"start"},"expected_end_next_start_locator":{"basis":"canonical-source-map","source_node_id":"o-evangelho-segundo-o-espiritismo:section:4a8392a915cbbe72","source_pdf_page":10,"printed_page":null,"locator":{"type":"paragraph_range","value":"73 e 74"},"boundary_role":"start"},"expected_successor_segment_key":"cb915263e3c99388da7ae878","expected_successor_segment_order":225},{"run_id":"adcff561-8f92-545c-a219-615818a454f4","book_id":3,"segment_key":"cb915263e3c99388da7ae878","segment_order":225,"decision_id":"54ba6e1af62927dcaef907b8","resolution_id":"33ddaa1693c9c31078718cfc","expected_start_locator":{"basis":"canonical-source-map","source_node_id":"o-evangelho-segundo-o-espiritismo:section:4a8392a915cbbe72","source_pdf_page":10,"printed_page":null,"locator":{"type":"paragraph_range","value":"73 e 74"},"boundary_role":"start"},"expected_end_next_start_locator":{"basis":"canonical-source-map","source_node_id":"o-evangelho-segundo-o-espiritismo:section:3a7a259cd6b62159","source_pdf_page":10,"printed_page":null,"locator":{"type":"paragraph_range","value":"75 e 76"},"boundary_role":"start"},"expected_successor_segment_key":"3fd64fbae1ef05b540c77c50","expected_successor_segment_order":226},{"run_id":"adcff561-8f92-545c-a219-615818a454f4","book_id":3,"segment_key":"b0ec6aeee66040321962cff4","segment_order":227,"decision_id":"b0b4df9a4322802740cf50cd","resolution_id":"3e3d4ca09a7888ffb2939f91","expected_start_locator":{"basis":"canonical-source-map","source_node_id":"o-evangelho-segundo-o-espiritismo:section:a336a8f28c402538","source_pdf_page":11,"printed_page":null,"locator":{"type":"paragraph_range","value":"77 a 80"},"boundary_role":"start"},"expected_end_next_start_locator":{"basis":"canonical-source-map","source_node_id":"o-evangelho-segundo-o-espiritismo:section:fea5b54b1bf84bbd","source_pdf_page":11,"printed_page":null,"locator":{"type":"paragraph_range","value":"81 a 84"},"b