  ) as target (
    run_id uuid,
    book_id integer,
    segment_key text,
    segment_order integer,
    decision_id text,
    resolution_id text,
    expected_start_locator jsonb,
    expected_end_next_start_locator jsonb,
    expected_successor_segment_key text,
    expected_successor_segment_order integer
  )
)
select
  checks.check_key,
  checks.severity,
  checks.passed,
  checks.actual_value,
  checks.details
from (
select
  'migration-run-status'::text as check_key,
  'blocking'::text as severity,
  (select status
      from content_staging.migration_runs
      where id = 'adcff561-8f92-545c-a219-615818a454f4'::uuid
    ) = 'reviewing' as passed,
  (select status
      from content_staging.migration_runs
      where id = 'adcff561-8f92-545c-a219-615818a454f4'::uuid)::text as actual_value,
  jsonb_build_object('expected', 'reviewing') as details
union all
select
  'rights-status'::text as check_key,
  'blocking'::text as severity,
  (select rights_status
      from content_staging.migration_runs
      where id = 'adcff561-8f92-545c-a219-615818a454f4'::uuid
    ) = 'blocked' as passed,
  (select rights_status
      from content_staging.migration_runs
      where id = 'adcff561-8f92-545c-a219-615818a454f4'::uuid)::text as actual_value,
  jsonb_build_object('expected', 'blocked') as details
union all
select
  'reading-segment-total'::text as check_key,
  'blocking'::text as severity,
  (select count(*)
      from content_staging.reading_segments
      where run_id = 'adcff561-8f92-545c-a219-615818a454f4'::uuid
    ) = 812 as passed,
  (select count(*)
      from content_staging.reading_segments
      where run_id = 'adcff561-8f92-545c-a219-615818a454f4'::uuid)::text as actual_value,
  jsonb_build_object('expected', 812) as details
union all
select
  'target-manifest-count'::text as check_key,
  'blocking'::text as severity,
  (select count(*) from targets) = 166 as passed,
  (select count(*) from targets)::text as actual_value,
  jsonb_build_object('expected', 166) as details
union all
select
  'target-key-uniqueness'::text as check_key,
  'blocking'::text as severity,
  (select count(*) from targets) =
      (select count(distinct segment_key) from targets) as passed,
  (select count(*) - count(distinct segment_key)
      from targets)::text as actual_value,
  jsonb_build_object('expected_duplicates', 0) as details
union all
select
  'target-rows-present'::text as check_key,
  'blocking'::text as severity,
  (select count(*)
      from targets target
      join content_staging.reading_segments segment
        on segment.run_id = target.run_id
       and segment.book_id = target.book_id
       and segment.segment_key = target.segment_key
    ) = 166 as passed,
  (select count(*)
      from targets target
      join content_staging.reading_segments segment
        on segment.run_id = target.run_id
       and segment.book_id = target.book_id
       and segment.segment_key = target.segment_key)::text as actual_value,
  jsonb_build_object('expected', 166) as details
union all
select
  'target-boundary-review-count'::text as check_key,
  'blocking'::text as severity,
  (select count(*)
      from targets target
      join content_staging.reading_segments segment
        on segment.run_id = target.run_id
       and segment.book_id = target.book_id
       and segment.segment_key = target.segment_key
      where segment.approval_status = 'boundary-review'
    ) = 166 as passed,
  (select count(*)
      from targets target
      join content_staging.reading_segments segment
        on segment.run_id = target.run_id
       and segment.book_id = target.book_id
       and segment.segment_key = target.segment_key
      where segment.approval_status = 'boundary-review')::text as actual_value,
  jsonb_build_object('expected', 166) as details
union all
select
  'content-review-before-application'::text as check_key,
  'blocking'::text as severity,
  (select count(*)
      from content_staging.reading_segments
      where run_id = 'adcff561-8f92-545c-a219-615818a454f4'::uuid
        and approval_status = 'content-review'
    ) = 0 as passed,
  (select count(*)
      from content_staging.reading_segments
      where run_id = 'adcff561-8f92-545c-a219-615818a454f4'::uuid
        and approval_status = 'content-review')::text as actual_value,
  jsonb_build_object('expected', 0) as details
union all
select
  'target-content-remains-null'::text as check_key,
  'blocking'::text as severity,
  not exists (
      select 1
      from targets target
      join content_staging.reading_segments segment
        on segment.run_id = target.run_id
       and segment.book_id = target.book_id
       and segment.segment_key = target.segment_key
      where segment.content is not null
         or segment.word_count is not null
         or segment.normalized_content_sha256 is not null
    ) as passed,
  (select count(*)
      from targets target
      join content_staging.reading_segments segment
        on segment.run_id = target.run_id
       and segment.book_id = target.book_id
       and segment.segment_key = target.segment_key
      where segment.content is not null
         or segment.word_count is not null
         or segment.normalized_content_sha256 is not null)::text as actual_value,
  jsonb_build_object('expected', 0) as details
union all
select
  'target-start-locator-match'::text as check_key,
  'blocking'::text as severity,
  not exists (
      select 1
      from targets target
      join content_staging.reading_segments segment
        on segment.run_id = target.run_id
       and segment.book_id = target.book_id
       and segment.segment_key = target.segment_key
      where segment.start_locator is distinct from
        target.expected_start_locator
    ) as passed,
  (select count(*)
      from targets target
      join content_staging.reading_segments segment
        on segment.run_id = target.run_id
       and segment.book_id = target.book_id
       and segment.segment_key = target.segment_key
      where segment.start_locator is distinct from
        target.expected_start_locator)::text as actual_value,
  jsonb_build_object('expected_mismatches', 0) as details
union all
select
  'target-end-successor-locator-match'::text as check_key,
  'blocking'::text as severity,
  not exists (
      select 1
      from targets target
      join content_staging.reading_segments segment
        on segment.run_id = target.run_id
       and segment.book_id = target.book_id
       and segment.segment_key = target.segment_key
      where segment.end_locator -> 'next_start_locator'
        is distinct from
        target.expected_end_next_start_locator
    ) as passed,
  (select count(*)
      from targets target
      join content_staging.reading_segments segment
        on segment.run_id = target.run_id
       and segment.book_id = target.book_id
       and segment.segment_key = target.segment_key
      where segment.end_locator -> 'next_start_locator'
        is distinct from
        target.expected_end_next_start_locator)::text as actual_value,
  jsonb_build_object('expected_mismatches', 0) as details
union all
select
  'target-successor-key-match'::text as check_key,
  'blocking'::text as severity,
  not exists (
      select 1
      from targets target
      join content_staging.reading_segments segment
        on segment.run_id = target.run_id
       and segment.book_id = target.book_id
       and segment.segment_key = target.segment_key
      where segment.end_locator ->> 'next_segment_key'
        is distinct from
        target.expected_successor_segment_key
    ) as passed,
  (select count(*)
      from targets target
      join content_staging.reading_segments segment
        on segment.run_id = target.run_id
       and segment.book_id = target.book_id
       and segment.segment_key = target.segment_key
      where segment.end_locator ->> 'next_segment_key'
        is distinct from
        target.expected_successor_segment_key)::text as actual_value,
  jsonb_build_object('expected_mismatches', 0) as details
union all
select
  'unaffected-segment-count'::text as check_key,
  'blocking'::text as severity,
  (select count(*)
      from content_staging.reading_segments segment
      where segment.run_id = 'adcff561-8f92-545c-a219-615818a454f4'::uuid
        and not exists (
          select 1
          from targets target
          where target.run_id = segment.run_id
            and target.book_id = segment.book_id
            and target.segment_key = segment.segment_key
        )
    ) = 646 as passed,
  (select count(*)
      from content_staging.reading_segments segment
      where segment.run_id = 'adcff561-8f92-545c-a219-615818a454f4'::uuid
        and not exists (
          select 1
          from targets target
          where target.run_id = segment.run_id
            and target.book_id = segment.book_id
            and target.segment_key = segment.segment_key
        ))::text as actual_value,
  jsonb_build_object('expected', 646) as details
union all
select
  'successor-mapping-count'::text as check_key,
  'blocking'::text as severity,
  (select count(*)
      from content_staging.current_successor_mappings
    ) = 0 as passed,
  (select count(*)
      from content_staging.current_successor_mappings)::text as actual_value,
  jsonb_build_object('expected', 0) as details
union all
select
  'dependency-snapshot-count'::text as check_key,
  'blocking'::text as severity,
  (select count(*)
      from content_staging.dependency_snapshots
    ) = 0 as passed,
  (select count(*)
      from content_staging.dependency_snapshots)::text as actual_value,
  jsonb_build_object('expected', 0) as details
union all
select
  'dry-run-result-count'::text as check_key,
  'blocking'::text as severity,
  (select count(*)
      from content_staging.dry_run_results
    ) = 0 as passed,
  (select count(*)
      from content_staging.dry_run_results)::text as actual_value,
  jsonb_build_object('expected', 0) as details
union all
select
  'prior-application-audit-event-count'::text as check_key,
  'blocking'::text as severity,
  (select count(*)
      from content_staging.migration_audit_events
      where run_id = 'adcff561-8f92-545c-a219-615818a454f4'::uuid
        and event_type =
          'mechanical-boundary-decisions-applied'
    ) = 0 as passed,
  (select count(*)
      from content_staging.migration_audit_events
      where run_id = 'adcff561-8f92-545c-a219-615818a454f4'::uuid
        and event_type =
          'mechanical-boundary-decisions-applied')::text as actual_value,
  jsonb_build_object('expected', 0) as details
union all
select
  'production-section-count'::text as check_key,
  'blocking'::text as severity,
  (select count(*) from public.sections) = 908 as passed,
  (select count(*) from public.sections)::text as actual_value,
  jsonb_build_object('expected', 908) as details
union all
select
  'application-roles-denied'::text as check_key,
  'blocking'::text as severity,
  not has_schema_privilege(
    'anon',
    'content_staging',
    'usage'
  )
  and not has_schema_privilege(
    'authenticated',
    'content_staging',
    'usage'
  ) as passed,
  (select (
      has_schema_privilege(
        'anon',
        'content_staging',
        'usage'
      )
      or has_schema_privilege(
        'authenticated',
        'content_staging',
        'usage'
      )
    ))::text as actual_value,
  jsonb_build_object('expected_any_access', false) as details
) checks
order by checks.check_key;
